/* ============================================================
   أطياب الجاسم (React) — معلومات المستخدم (UserInfo)

   أربعة أقسام داخل كومبوننت واحد، كما طُلب:
     1) بطاقة صغيرة على الجانب: الصورة الرمزية، الاسم، البريد، والوقائع
        (الدولة · اللغة · العملة · حالة عنوان التوصيل).
     2) حقل البيانات الأساسية: الاسم، الاسم الأخير، مصدر الهاتف + الهاتف،
        البريد، الدولة، اللغة، العملة + «حفظ التغيّرات» — كلها مطلوبة.
     3) لوحة العنوان للتوصيل (تظهر عند الضغط على رابط «إكمال العنوان»):
        المدينة (من مدن الدولة المختارة فقط)، الحي، الشارع، رقم المبنى،
        الرمز البريدي، أقرب معلَم، نوع العنوان، الملاحظات،
        العنوان الافتراضي + «حفظ العنوان».
     4) شريط الحالة/الأزرار (محفوظ · تغييرات غير محفوظة · إلغاء).

   ★ الدولة = مفتاح ثابت (AE/SA/…) من ATYAB_COUNTRIES — وتغييرها يضبط
     تلقائياً: العملة + مصدر الهاتف + قائمة المدن (وتُصفَّر المدينة إن لم
     تكن من مدن الدولة الجديدة). تغيير العميل لمصدر الهاتف يدوياً يُحترم
     ولا يُجبَر ثانيةً إلا بتغيير الدولة من جديد.
   ★ الحفظ يمرّ عبر validation.js أولاً ثم إلى Redux (userSlice).
   ============================================================ */

import { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { PATHS } from "../../routes.js";
import { ATYAB_LANGUAGES, ATYAB_CURRENCIES, ATYAB_COUNTRIES, countryByKey, citiesOfCountry } from "../../data/appConfig.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { userActions } from "../../redux/slices/userSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { currencyMeta, makeMoney } from "../../redux/selectors.js";
import { validateProfile, validateAddress, POSTAL_LENGTH, cleanText, splitPhone, joinPhone, isNewCustomerProfile } from "../../validation.js";
import { fetchCustomerData, saveProfileSmart, saveLocationSmart } from "../../redux/slices/customerSlice.js";
import { loadGeo, serverCityOptions } from "../../redux/slices/geoSlice.js";
import { fromLocation } from "../../api/customers.js";
import { toUserMessage } from "../../api/friendlyError.js";
import { tr2 } from "../../i18n.js";
import { Icon } from "../Source/Icons.jsx";

/* بنية خيارات القائمة المنسدلة بلغة الواجهة: {key, label} */
function optionsIn(list, lang) {
  return (list || []).map(function (it) {
    return { key: it.key, label: lang === "en" ? it.labelEn || it.label : it.label };
  });
}

function shortLabel(label) {
  return String(label == null ? "" : label).replace(/\s*\([^)]*\)\s*$/, "").trim();
}

function byKey(list, key) {
  for (let i = 0; i < list.length; i++) {
    if (String(list[i].key) === String(key)) return list[i];
  }
  return null;
}

function stamp(ts) {
  const d = new Date(Number(ts) || 0);
  return ("0" + d.getHours()).slice(-2) + ":" + ("0" + d.getMinutes()).slice(-2);
}

const EMAIL_FIELDS = ["firstName", "lastName", "email", "phoneCode", "phone", "region", "language", "currency"];
const ADDRESS_FIELDS = ["city", "district", "street", "building", "postal", "landmark", "notes"];

/* النموذج من الملف المحفوظ: الرقم الكامل يُقسَّم إلى (رمز + محلي) للعرض */
function applyProfile(p) {
  const base = Object.assign({}, p);
  const parts = splitPhone(base.phone, base.phoneCode);
  base.phoneCode = parts.code;
  base.phone = parts.local;
  return base;
}

/* اسم الدولة بلغة الواجهة — للبطاقة الجانبية */
function countryLabel(key, lang) {
  const c = countryByKey(key);
  if (!c) return "";
  return lang === "en" ? c.labelEn || c.label : c.label;
}

export default function UserInfo() {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const profile = useAppSelector(function (s) {
    return s.user.profile;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  const [form, setForm] = useState(function () {
    return applyProfile(profile);
  });
  const [address, setAddress] = useState(profile.address);
  const [errors, setErrors] = useState({});
  const [addressErrors, setAddressErrors] = useState({});
  const [addressOpen, setAddressOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [serverApplied, setServerApplied] = useState(false);
  const customerId = useAppSelector(function (s) {
    return s.user.auth && s.user.auth.customerId;
  });
  const serverDetails = useAppSelector(function (s) {
    return s.customer.details;
  });
  const serverLocations = useAppSelector(function (s) {
    return s.customer.locations || [];
  });

  useEffect(function () {
    if (customerId) dispatch(fetchCustomerData(Number(customerId)));
  }, [customerId, dispatch]);

  useEffect(function () {
    dispatch(loadGeo());
  }, [dispatch]);

  const geo = useAppSelector(function (s) { return s.geo; });
  const profileCityOptions = useMemo(function () {
    return serverCityOptions(geo, form.region, language) || citiesOfCountry(form.region, language);
  }, [geo, form.region, language]);

  useEffect(function () {
    if (serverApplied || !serverDetails) return;
    const looksNew = isNewCustomerProfile(serverDetails);
    if (!looksNew) {
      const parts = splitPhone(serverDetails.phoneNumber || "", "971");
      setForm(function (prev) {
        const next = Object.assign({}, prev);
        if (!next.firstName && serverDetails.firstName) next.firstName = serverDetails.firstName;
        if (!next.lastName && serverDetails.lastName) next.lastName = serverDetails.lastName;
        if (serverDetails.phoneNumber) {
          next.phoneCode = parts.code;
          next.phone = parts.local;
        }
        return next;
      });
    }
    const first = serverLocations.filter(function (l) { return !!l.isDefault; })[0] || serverLocations[0];
    if (first) {
      const mapped = fromLocation(first);
      setAddress(function (prev) {
        const empty = !prev.city && !prev.district && !prev.street && !prev.building;
        if (!empty) return prev;
        return Object.assign({}, prev, {
          city: mapped.city || prev.city,
          district: mapped.district || prev.district,
          street: mapped.street || prev.street,
          building: mapped.building || prev.building,
          postal: mapped.postal || prev.postal,
          landmark: mapped.landmark || prev.landmark,
          notes: mapped.notes || prev.notes,
          type: mapped.type || prev.type,
          isDefault: first.isDefault != null ? !!first.isDefault : prev.isDefault
        });
      });
    }
    setServerApplied(true);
  }, [serverDetails, serverLocations, serverApplied]);

  /* نُزامن الحقول عند تغيّر الملف المحفوظ (تسجيل دخول/استرجاع).
     ★ الضبط يحدث أثناء الرسم لا داخل effect: هذه هي طريقة React
       المعتمدة لـ«إعادة ضبط الحالة عند تغيّر مصدرها» — نقارن نسخة
       معروفة، فإن اختلفت ضبطنا الحالة مرة واحدة وأعاد React الرسم
       فوراً. وبها لا رسم متتالٍ في effect، ولا مخالفة لقاعدة
       set-state-in-effect (وهي قاعدة React Compiler نفسها). */
  const profileVersion = String(profile.updatedAt || "") + "|" + String(profile.addressUpdatedAt || "");
  const [syncedVersion, setSyncedVersion] = useState(profileVersion);
  if (syncedVersion !== profileVersion) {
    setSyncedVersion(profileVersion);
    setForm(applyProfile(profile));
    setAddress(profile.address);
  }

  const dirty = useMemo(
    function () {
      return EMAIL_FIELDS.some(function (k) {
        return String(form[k] || "") !== String(profile[k] || "");
      });
    },
    [form, profile]
  );

  const addressDirty = useMemo(
    function () {
      return ADDRESS_FIELDS.some(function (k) {
        return String(address[k] || "") !== String(profile.address[k] || "");
      }) || String(address.type || "") !== String(profile.address.type || "") || !!address.isDefault !== !!profile.address.isDefault;
    },
    [address, profile.address]
  );

  const addressComplete = useMemo(
    function () {
      const a = profile.address;
      return !!(
        cleanText(a.city) &&
        cleanText(a.district) &&
        cleanText(a.street) &&
        cleanText(a.building) &&
        /^\d{5}$/.test(cleanText(a.postal))
      );
    },
    [profile.address]
  );

  function setField(key, value) {
    setForm(function (prev) {
      return Object.assign({}, prev, { [key]: value });
    });
    setErrors(function (prev) {
      return Object.assign({}, prev, { [key]: "" });
    });
  }

  function setAddr(key, value) {
    setAddress(function (prev) {
      return Object.assign({}, prev, { [key]: value });
    });
    setAddressErrors(function (prev) {
      return Object.assign({}, prev, { [key]: "" });
    });
  }

  function save() {
    const result = validateProfile(form);
    setErrors(result.errors);
    if (!result.valid) {
      dispatch(uiActions.toastShown("أكمل البيانات المطلوبة: " + result.firstError));
      return;
    }
    const patch = {
      firstName: cleanText(form.firstName),
      lastName: cleanText(form.lastName),
      email: cleanText(form.email).toLowerCase(),
      phoneCode: String(form.phoneCode || "971").replace(/\D/g, ""),
      phone: joinPhone(form.phoneCode, form.phone),
      region: form.region,
      language: form.language,
      currency: form.currency
    };
    dispatch(userActions.setProfile(patch));
    if (form.language !== language) dispatch(uiActions.setLanguage(form.language));
    if (!customerId) {
      dispatch(uiActions.toastShown("تم حفظ التغيّرات على هذا الجهاز"));
      navigate(PATHS.perfumes);
      return;
    }
    setBusy(true);
    dispatch(saveProfileSmart({
      customerId: Number(customerId),
      firstName: patch.firstName,
      lastName: patch.lastName,
      phoneNumber: patch.phone
    })).unwrap().then(function (out) {
      setBusy(false);
      dispatch(uiActions.toastShown(out && out.mode === "add" ? "تم إنشاء بياناتك بنجاح" : "تم تحديث بياناتك بنجاح"));
      navigate(PATHS.perfumes);
    }, function (err) {
      setBusy(false);
      dispatch(uiActions.toastShown(toUserMessage(err, language) || (language === "en" ? "Couldn't save — try again." : "تعذّر الحفظ — حاول مجددًا.")));
    });
  }

  function saveAddress() {
    const cities = profileCityOptions.map(function (c) {
      return c.key;
    });
    if (cities.length && address.city && cities.indexOf(address.city) === -1) {
      setAddressErrors({ city: "اختر المدينة من القائمة." });
      dispatch(uiActions.toastShown("اختر المدينة من القائمة."));
      return;
    }
    const result = validateAddress(address);
    setAddressErrors(result.errors);
    if (!result.valid) {
      dispatch(uiActions.toastShown("أكمل بيانات العنوان: " + result.firstError));
      return;
    }
    dispatch(userActions.setAddress(address));
    if (!customerId) {
      dispatch(uiActions.toastShown("تم حفظ عنوان التوصيل على هذا الجهاز"));
      return;
    }
    setBusy(true);
    dispatch(saveLocationSmart({
      customerId: Number(customerId),
      form: Object.assign({}, address, { region: form.region })
    })).unwrap().then(function (out) {
      setBusy(false);
      dispatch(uiActions.toastShown(out && out.mode === "add" ? "تمت إضافة عنوانك بنجاح" : "تم تحديث عنوانك بنجاح"));
    }, function (err) {
      setBusy(false);
      dispatch(uiActions.toastShown(toUserMessage(err, language) || (language === "en" ? "Couldn't save the address — try again." : "تعذّر حفظ العنوان — حاول مجددًا.")));
    });
  }

  /* تغيير الدولة: عملة + مصدر هاتف + مدن جديدة تلقائياً.
     (تغيير العميل لمصدر الهاتف يدوياً بعد ذلك يُحترم — لا نجبره هنا) */
  function onRegionChange(key) {
    const c = countryByKey(key);
    setField("region", key);
    if (c) {
      setField("currency", c.currency);
      setField("phoneCode", c.phoneCode);
      const keys = (serverCityOptions(geo, key, "ar") || citiesOfCountry(key, "ar")).map(function (m) {
        return m.key;
      });
      if (address.city && keys.indexOf(address.city) === -1) setAddr("city", "");
    }
  }

  const fullName = [profile.firstName, profile.lastName].filter(Boolean).join(" ").trim();
  let initials =
    (profile.firstName || "").trim().charAt(0) + " " + (profile.lastName || "").trim().charAt(0);
  initials = initials.trim() || (profile.email || "؟").charAt(0).toUpperCase();
  const curr = currencyMeta(profile.currency);
  const sampleMoney = makeMoney(language, profile.currency).format(389);

  /* ---------- أداة: حقل إدخال ---------- */
  function field(o) {
    const bad = !!errors[o.name];
    const control =
      o.tag === "select" ? (
        <select
          className="pf-input pf-select pf-control"
          id={"pf" + o.name}
          value={form[o.name] || ""}
          onChange={function (e) {
            if (o.onChange) o.onChange(e.target.value);
            else setField(o.name, e.target.value);
          }}
        >
          {o.placeholder ? <option value="">{o.placeholder}</option> : null}
          {(o.options || []).map(function (opt) {
            return (
              <option key={opt.key} value={opt.key}>
                {opt.label}
              </option>
            );
          })}
        </select>
      ) : (
        <input
          className={"pf-input pf-control" + (bad ? " is-bad" : "")}
          id={"pf" + o.name}
          type={o.type || "text"}
          dir={o.dir}
          inputMode={o.inputMode}
          maxLength={o.maxLength}
          autoComplete={o.autoComplete}
          placeholder={o.placeholder}
          aria-invalid={bad ? "true" : undefined}
          value={form[o.name] == null ? "" : form[o.name]}
          onChange={function (e) {
            setField(o.name, e.target.value);
          }}
        />
      );
    return (
      <div className={"pf-field" + (o.wide ? " is-wide" : "") + (bad ? " is-bad" : "")}>
        <label className="pf-label" htmlFor={"pf" + o.name}>
          {o.label} <em>{o.req ? "مطلوب" : "اختياري"}</em>
        </label>
        {control}
        <p className="pf-err">{errors[o.name] || ""}</p>
      </div>
    );
  }

  /* ---------- أداة: حقل عنوان ---------- */
  function addrField(o) {
    const bad = !!addressErrors[o.name];
    const value = address[o.name] == null ? "" : address[o.name];
    let control;
    if (o.tag === "select") {
      control = (
        <select
          className="pf-input pf-select pf-control"
          id={"ad" + o.name}
          value={value}
          onChange={function (e) {
            setAddr(o.name, e.target.value);
          }}
        >
          {o.placeholder ? <option value="">{o.placeholder}</option> : null}
          {(o.options || []).map(function (opt) {
            const key = opt && typeof opt === "object" ? opt.key : opt;
            const label = opt && typeof opt === "object" ? opt.label || opt.key : opt;
            return (
              <option key={key} value={key}>
                {label}
              </option>
            );
          })}
        </select>
      );
    } else if (o.tag === "textarea") {
      control = (
        <textarea
          className={"pf-input pf-control" + (bad ? " is-bad" : "")}
          id={"ad" + o.name}
          rows={3}
          placeholder={o.placeholder}
          value={value}
          onChange={function (e) {
            setAddr(o.name, e.target.value);
          }}
        />
      );
    } else {
      control = (
        <input
          className={"pf-input pf-control" + (bad ? " is-bad" : "")}
          id={"ad" + o.name}
          type={o.type || "text"}
          dir={o.dir}
          inputMode={o.inputMode}
          maxLength={o.maxLength}
          placeholder={o.placeholder}
          aria-invalid={bad ? "true" : undefined}
          value={value}
          onChange={function (e) {
            setAddr(o.name, e.target.value);
          }}
        />
      );
    }
    return (
      <div className={"pf-field" + (o.wide ? " is-wide" : "") + (bad ? " is-bad" : "")}>
        <label className="pf-label" htmlFor={"ad" + o.name}>
          {o.label} <em>{o.req ? "مطلوب" : "اختياري"}</em>
        </label>
        {control}
        <p className="pf-err">{addressErrors[o.name] || ""}</p>
      </div>
    );
  }

  return (
    <div className="pf-body">
      {/* ---------- 1) بطاقة التعريف ---------- */}
      <aside className="pf-side">
        <div className="pf-avatar" aria-hidden="true">
          {initials}
        </div>
        <div>
          <p className="pf-side-name">{fullName || "زائر جديد"}</p>
          <p className="pf-side-mail">{profile.email || "لم تُضف بريدك بعد"}</p>
        </div>
        <ul className="pf-facts">
          <li>
            <span>الدولة</span>
            <b className={profile.region ? "" : "is-wait"}>{countryLabel(profile.region, language) || "غير محدّدة"}</b>
          </li>
          <li>
            <span>اللغة</span>
            <b>
              {language === "en"
                ? (byKey(ATYAB_LANGUAGES, profile.language) || {}).labelEn || "Arabic"
                : (byKey(ATYAB_LANGUAGES, profile.language) || {}).label || "العربية"}
            </b>
          </li>
          <li>
            <span>العملة</span>
            <b>
              {language === "en"
                ? shortLabel((byKey(ATYAB_CURRENCIES, profile.currency) || {}).labelEn) || "UAE Dirham"
                : shortLabel((byKey(ATYAB_CURRENCIES, profile.currency) || {}).label) || "درهم إماراتي"}
            </b>
          </li>
          <li>
            <span>عنوان التوصيل</span>
            <b className={addressComplete ? "is-ok" : "is-wait"}>{addressComplete ? "مكتمل ✓" : "غير مكتمل"}</b>
          </li>
        </ul>
        <p className="pf-hint">
          {sampleMoney ? tr2(language, "Example: a 389 AED perfume shows as ", "مثال: عطر بـ 389 د.إ سيظهر ") + sampleMoney + "." : ""}
        </p>
      </aside>

      <div className="pf-main">
        {/* ---------- 2) البيانات الأساسية ---------- */}
        <div className="pf-card">
          <div className="pf-card-head">
            <div>
              <h2>البيانات الشخصية</h2>
              <p>تُحفظ على هذا الجهاز فقط.</p>
            </div>
            <span className={"pf-status" + (dirty ? " is-dirty" : profile.updatedAt ? " is-saved" : "")}>
              {dirty ? "تغييرات غير محفوظة" : profile.updatedAt ? "محفوظ • " + stamp(profile.updatedAt) : "لم يُحفظ بعد"}
            </span>
          </div>

          <form
            className="pf-fields"
            noValidate
            onSubmit={function (e) {
              e.preventDefault();
              save();
            }}
          >
            {field({ name: "firstName", label: "الاسم", req: true, type: "text", autoComplete: "given-name", placeholder: "مثال: عبدالله" })}
            {field({ name: "lastName", label: "الاسم الأخير", req: true, type: "text", autoComplete: "family-name", placeholder: "مثال: الجاسم" })}
            <div className={"pf-field" + (errors.phone ? " is-bad" : "")}>
              <label className="pf-label" htmlFor="pfphone">
                رقم الهاتف <em>مطلوب</em>
              </label>
              <div className="pf-phone-row">
                <select
                  className="pf-input pf-select pf-control pf-phone-code"
                  id="pfphoneCode"
                  dir="ltr"
                  aria-label="مصدر الهاتف"
                  value={form.phoneCode || "971"}
                  onChange={function (e) {
                    setField("phoneCode", e.target.value.replace(/\D/g, ""));
                  }}
                >
                  {(ATYAB_COUNTRIES || []).map(function (c) {
                    const short = language === "en" ? c.shortEn || c.short : c.short || c.label;
                    return (
                      <option key={c.key} value={c.phoneCode}>
                        +{c.phoneCode} — {short}
                      </option>
                    );
                  })}
                </select>
                <input
                  className={"pf-input pf-control" + (errors.phone ? " is-bad" : "")}
                  id="pfphone"
                  type="tel"
                  dir="ltr"
                  inputMode="tel"
                  autoComplete="tel"
                  placeholder="5XXXXXXXX"
                  aria-invalid={errors.phone ? "true" : undefined}
                  value={form.phone == null ? "" : form.phone}
                  onChange={function (e) {
                    setField("phone", e.target.value);
                  }}
                />
              </div>
              <p className="pf-err">{errors.phone || ""}</p>
            </div>
            {field({ name: "email", label: "البريد الإلكتروني", req: true, type: "email", dir: "ltr", autoComplete: "email", placeholder: "name@example.com", wide: true })}
            {field({
              name: "region",
              label: "الدولة",
              req: true,
              tag: "select",
              wide: true,
              placeholder: "— اختر الدولة —",
              onChange: onRegionChange,
              options: (ATYAB_COUNTRIES || []).map(function (c) {
                return { key: c.key, label: language === "en" ? c.labelEn || c.label : c.label };
              })
            })}
            {field({ name: "language", label: "اللغة", tag: "select", options: optionsIn(ATYAB_LANGUAGES, language) })}
            {field({ name: "currency", label: "العملة", tag: "select", options: optionsIn(ATYAB_CURRENCIES, language) })}
          </form>

          <div className="pf-actions">
            <button className="pf-save" type="button" onClick={save} disabled={busy}>
              <Icon name="save" strokeWidth={1.9} />
              <span>{busy ? "يُحفظ…" : "حفظ التغيّرات"}</span>
            </button>
            <span className="pf-hint">{curr && curr.key === "AED" ? "" : "الأسعار ستُعرض بعملتك المختارة."}</span>
          </div>
        </div>

        {/* ---------- 3) العنوان للتوصيل ---------- */}
        <div className="pf-address">
          <button
            className="pf-address-link"
            type="button"
            aria-expanded={addressOpen ? "true" : "false"}
            aria-controls="pfAddressPanel"
            onClick={function () {
              setAddressOpen(!addressOpen);
            }}
          >
            <Icon name="pin" strokeWidth={1.8} />
            <span>
              إكمال العنوان للتوصيل
              <span className="pf-address-meta">
                {addressComplete
                  ? "✓ " +
                    [profile.address.type === "work" ? "العمل" : "المنزل", profile.address.street, profile.address.district, profile.address.city, profile.address.postal]
                      .filter(Boolean)
                      .join(" — ")
                  : "اضغط هنا لإكمال متطلبات العنوان السكني (المدينة، المنطقة، الشارع، رقم المبنى، الرمز البريدي)."}
              </span>
            </span>
            <Icon name="chev" className="pf-address-chev" strokeWidth={2.2} />
          </button>

          {addressOpen ? (
            <div className="pf-address-panel" id="pfAddressPanel">
              <h3>متطلبات العنوان السكني</h3>
              <p className="pf-address-req">
                <b>لكي نتمكّن من التوصيل نحتاج:</b> المدينة، المنطقة، اسم الشارع، رقم المبنى، الرمز البريدي (
                {POSTAL_LENGTH} أرقام)، وأقرب معلَم يسهّل وصول المندوب. ويمكنك تحديد نوع العنوان وجعله العنوان الافتراضي.
              </p>

              <form
                className="pf-fields"
                noValidate
                onSubmit={function (e) {
                  e.preventDefault();
                  saveAddress();
                }}
              >
                {addrField({ name: "city", label: "المدينة", req: true, tag: "select", wide: true, placeholder: "— اختر المدينة —", options: profileCityOptions })}
                {addrField({ name: "district", label: "المنطقة", req: true, placeholder: "مثال: الملقا" })}
                {addrField({ name: "street", label: "الشارع", req: true, placeholder: "مثال: طريق الملك فهد" })}
                {addrField({ name: "building", label: "رقم المبنى", req: true, inputMode: "numeric", maxLength: 6, placeholder: "مثال: 3124" })}
                {addrField({ name: "postal", label: "الرمز البريدي", req: true, inputMode: "numeric", maxLength: 5, dir: "ltr", placeholder: "13521" })}
                {addrField({ name: "landmark", label: "أقرب معلَم", wide: true, placeholder: "مثال: مقابل جامع الأمير سلطان" })}

                <div className="pf-field is-wide">
                  <span className="pf-label">
                    نوع العنوان <em>اختياري</em>
                  </span>
                  <div className="pf-pills" role="group" aria-label="نوع العنوان">
                    <button
                      className="pf-pill"
                      type="button"
                      aria-pressed={address.type === "home" ? "true" : "false"}
                      onClick={function () {
                        setAddr("type", "home");
                      }}
                    >
                      المنزل
                    </button>
                    <button
                      className="pf-pill"
                      type="button"
                      aria-pressed={address.type === "work" ? "true" : "false"}
                      onClick={function () {
                        setAddr("type", "work");
                      }}
                    >
                      العمل
                    </button>
                  </div>
                </div>

                {addrField({ name: "notes", label: "ملاحظات للمندوب", tag: "textarea", wide: true, placeholder: "مثال: البوابة الثانية، الاتصال قبل الوصول" })}

                <div className="pf-field is-wide">
                  <label className="pf-check">
                    <input
                      type="checkbox"
                      checked={!!address.isDefault}
                      onChange={function (e) {
                        setAddr("isDefault", e.target.checked);
                      }}
                    />{" "}
                    اجعله عنواني الافتراضي
                  </label>
                </div>
              </form>

              <div className="pf-actions">
                <button className="pf-save" type="button" onClick={saveAddress} disabled={busy}>
                  <Icon name="save" strokeWidth={1.9} />
                  <span>{busy ? "يُحفظ…" : "حفظ العنوان"}</span>
                </button>
                <button
                  className="pf-reset"
                  type="button"
                  onClick={function () {
                    setAddressOpen(false);
                  }}
                >
                  إغلاق
                </button>
                <span className={"pf-status" + (addressDirty ? " is-dirty" : profile.addressUpdatedAt ? " is-saved" : "")}>
                  {addressDirty ? "تغييرات غير محفوظة" : profile.addressUpdatedAt ? "محفوظ • " + stamp(profile.addressUpdatedAt) : "غير محفوظ"}
                </span>
              </div>
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );
}
