/* ============================================================
   أطياب الجاسم (React) — سجلّ الطلبات (OrdersHistory)

   يُعرض في صفحة «حسابي» أسفل بيانات العميل: كل طلب أكّده العميل
   بطاقة واحدة فيها رقم الفاتورة وتاريخها وحالتها، القطع، طريقة الدفع،
   الإجمالي بالعملة التي دفع بها، ونافذة التسليم التقديرية.

   ★ الأرقام من سجلّ الطلب نفسه (ordersSlice) لا من الأسعار الحالية —
     فالفاتورة القديمة تبقى كما أُصدرت.
   ★ زرّان مفيدان: «إعادة الطلب» (يُعيد القطع المتوفّرة إلى العربة)
     و«حذف من السجلّ» (يمسح البطاقة من متصفّح العميل فقط).
   ============================================================ */

import { useEffect, useMemo, useRef, useState } from "react";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { ordersActions, orderItemName, methodLabelOf, etaWindowOf, deliveryStateOf } from "../../redux/slices/ordersSlice.js";
import { fetchServerOrders, fetchServerOrderDetail, normalizeServerOrder, normalizeServerRow } from "../../api/orders.js";
import ShipmentCard from "./ShipmentCard.jsx";
import { downloadInvoicePdf } from "../../utils/invoicePdf.js";
import { addItem } from "../../redux/slices/cartSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { makeMoneyFrom, pad2 } from "../../redux/selectors.js";
import { ATYAB_byId } from "../../data/products.js";
import { Link, useLocation } from "react-router-dom";
import { PATHS } from "../../routes.js";
import { T, tr2 } from "../../i18n.js";
import { Icon } from "../Source/Icons.jsx";
import { ListRowsSkeleton } from "../Skeletons/index.js";
import "../../components/Skeletons/Skeletons.css";

/* اسم طريقة الدفع: من المفتاح المحفوظ بلغة الواجهة، وإلا الاسم المُجمَّد
   في الطلب القديم (فالفاتورة القديمة تبقى كما أُصدرت). */
function methodText(order, language) {
  return methodLabelOf(order.method, language) || T(order.methodLabel, language) || "—";
}

function stamp(ms) {
  const d = new Date(Number(ms) || 0);
  return pad2(d.getDate()) + "/" + pad2(d.getMonth() + 1) + "/" + d.getFullYear();
}

function countOf(order) {
  if (!order) return 0;
  if (order.totals && typeof order.totals.count === "number") return order.totals.count;
  return Number(order.itemsCount) || 0;
}

/* ★ لون الحالة (مطلوب): بانتظار = أصفر، مدفوع/مؤكد = أخضر، ملغي = أحمر.
   النصّ خام من الخادم (statusName) فيُكتشف بالكلمات ar/en */
function statusTone(order) {
  const s = [
    order && order.status && (order.status.ar || ""),
    order && order.status && (order.status.en || ""),
    order && order.paymentStatus
  ]
    .filter(Boolean)
    .join(" ")
    .toLowerCase();
  if (/cancel|ملغي|مرفوض|fail|فشل|refund|مسترجع|rejected|void/.test(s)) return "bad";
  if (/pend|بانتظار|معلق|قيد|انتظار|انتظار الدفع|processing|قيد المراجعة/.test(s)) return "wait";
  if (/paid|مدفوع|مؤكد|success|complete|مكتمل|ناجح|مقبول|approved|confirm|deliver|توصيل|shipped|جاهز/.test(s)) return "ok";
  return "";
}

const TONE_STYLE = {
  wait: { background: "rgba(217,165,33,.16)", color: "#e7b62a", border: "1px solid rgba(217,165,33,.55)" },
  ok: { background: "rgba(47,168,102,.14)", color: "#3ddc84", border: "1px solid rgba(47,168,102,.55)" },
  bad: { background: "rgba(217,83,79,.14)", color: "#ff7b72", border: "1px solid rgba(217,83,79,.55)" }
};

/* ★ نصّ الفاتورة للنسخ/التنزيل — من سجلّ الطلب نفسه (كما أُصدرت) */
function invoiceText(order, language, money) {
  const L = [];
  L.push("أطياب الجاسم — Atyab Al-Jasem");
  L.push(tr2(language, "Invoice: ", "فاتورة: ") + "#" + order.invoiceNo);
  L.push(tr2(language, "Date: ", "التاريخ: ") + stamp(order.createdAt));
  L.push(tr2(language, "Payment: ", "الدفع: ") + methodText(order, language));
  L.push(tr2(language, "Status: ", "الحالة: ") + T(order.status, language));
  L.push("— — —");
  (order.items || []).forEach(function (item) {
    L.push(orderItemName(item, language) + " × " + item.qty + " = " + money.format(item.lineTotal));
  });
  if (order.rowOnly) L.push(tr2(language, countOf(order) + " items", countOf(order) + " قطعة"));
  L.push("— — —");
  try {
    L.push(tr2(language, "Total: ", "الإجمالي: ") + money.format(order.totals.total));
  } catch (e) {
    L.push(tr2(language, "Total: ", "الإجمالي: ") + order.totals.total);
  }
  return L.join("\n");
}

function copyText(text, okMsg) {
  function done(dispatch) {
    dispatch(uiActions.toastShown(okMsg));
  }
  return function (dispatch) {
    if (navigator && navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(function () { done(dispatch); }, function () { fallbackCopy(dispatch); });
      return;
    }
    fallbackCopy(dispatch);
    function fallbackCopy(d) {
      try {
        const ta = document.createElement("textarea");
        ta.value = text;
        ta.style.position = "fixed";
        ta.style.opacity = "0";
        document.body.appendChild(ta);
        ta.select();
        document.execCommand("copy");
        document.body.removeChild(ta);
        done(d);
      } catch (e) {}
    }
  };
}

function OrderCard(props) {
  const dispatch = useAppDispatch();
  const language = props.language;
  const order = props.order;
  const customerId = props.customerId || null;
  const [pdfBusy, setPdfBusy] = useState(false);
  const money = useMemo(
    function () {
      return makeMoneyFrom(order.currency, language);
    },
    [order, language]
  );
  const eta = etaWindowOf(order);
  /* ★ v17-D1: الحالات من حقول الخادم الصريحة — لا استنتاج بالوقت */
  const dst = deliveryStateOf(order);
  const live = (order.items || []).filter(function (item) {
    return !!ATYAB_byId(item.id);
  });

  return (
    <article className="oh-card">
      <header className="oh-head">
        <div>
          <span className="oh-no">
            {tr2(language, "Invoice number", "رقم الفاتورة")} <b>#{order.invoiceNo}</b>
          </span>
          <span className="oh-date">
            {stamp(order.createdAt)} · {methodText(order, language)}
          </span>
        </div>
        <span className="ck-chip" style={TONE_STYLE[statusTone(order)] || undefined}>{T(order.status, language)}</span>
      </header>

      <ul className="oh-items">
        {(order.items || []).map(function (item) {
          return (
            <li key={item.id}>
              <span>
                {orderItemName(item, language)}
                <em>× {item.qty}</em>
              </span>
              <b>{money.format(item.lineTotal)}</b>
            </li>
          );
        })}
      </ul>

      {order.rowOnly ? (
        <p className="oh-sub">
          {tr2(language, countOf(order) + (countOf(order) === 1 ? " item" : " items"), countOf(order) + " قطعة")}
        </p>
      ) : null}

      <div className="oh-foot">
        <span className="oh-eta">
          <Icon name="truck" strokeWidth={1.8} />
          <span>
            {dst.isDelivered
              ? tr2(language, "Delivered", "تم التسليم")
              : tr2(language, "Delivery window: ", "نافذة التسليم: ")}
            {dst.isDelivered ? null : <>{stamp(eta.from)} → {stamp(eta.to)}</>}
            {eta.source === "estimate" && !dst.isDelivered ? tr2(language, " (estimate)", " (تقديرية)") : null}
          </span>
        </span>
        {/* ★ v17-D1: حالة الدفع الصريحة — COD غير مدفوع حتى التحصيل الفعلي */}
        <span className="oh-eta">
          <Icon name="card" strokeWidth={1.8} />
          <span>
            {dst.isPaid
              ? tr2(language, "Paid", "مدفوع")
              : dst.codDue
                ? tr2(language, "Due on delivery", "مستحق عند الاستلام")
                : tr2(language, "Payment pending", "بانتظار الدفع")}
          </span>
        </span>
        {/* ★ FE18-X03: سبب الانتقال التلقائي من الخادم — يُعرض كما وصل
            (سياسة تلقائية 24h/48h، ليست دليل استلام ميداني) */}
        {(order.autoNote || order.transitionReason || (order.delivery && (order.delivery.autoNote || order.delivery.reason))) ? (
          <span className="oh-eta">
            <Icon name="info" strokeWidth={1.8} />
            <span>
              {tr2(language, "Auto update: ", "تحديث تلقائي: ")}
              {String(order.autoNote || order.transitionReason || (order.delivery && (order.delivery.autoNote || order.delivery.reason)) || "")}
            </span>
          </span>
        ) : null}
        <span className="oh-total">
          <small>{tr2(language, "Order total", "إجمالي الطلب")}</small>
          <b>{money.format(order.totals.total)}</b>
        </span>
      </div>

      {/* ★ FE35: بطاقة شحنة الطلب — تُجلب عند طلب العميل فقط (زر «حالة
          الشحنة»)، وتُستطلع أثناء فتح تفاصيل طلب نشط فقط، وتتوقف عند
          إخفاء الصفحة أو الحالة النهائية. الخام لا يغيّر دفعاً/مرتجعاً. */}
      <ShipmentCard order={order} language={language} />

      <div className="oh-actions">
        {live.length ? (
          <button
            className="oh-btn is-gold"
            type="button"
            onClick={function () {
              live.forEach(function (item) {
                dispatch(addItem(item.id, item.qty));
              });
              dispatch(
                uiActions.toastShown(
                  tr2(
                    language,
                    "We returned " + live.length + (live.length === 1 ? " item" : " items") + " to the cart",
                    "أعدنا " + live.length + " قطعة إلى العربة"
                  )
                )
              );
            }}
          >
            <Icon name="cart" strokeWidth={1.8} />
            <span>إعادة الطلب</span>
          </button>
        ) : null}
        {/* ★ نسخ الفاتورة نصاً — للواتساب/الدعم */}
        <button
          className="oh-btn"
          type="button"
          onClick={function () {
            dispatch(
              copyText(
                invoiceText(order, language, money),
                tr2(language, "Invoice copied", "نُسخت الفاتورة")
              )
            );
          }}
        >
          <Icon name="doc" strokeWidth={1.8} />
          <span>نسخ الفاتورة</span>
        </button>
        {/* ★ تنزيل الفاتورة PDF حقيقي (متى/أين/المنتجات/الخصومات/التوصيل) */}
        <button
          className="oh-btn"
          type="button"
          disabled={pdfBusy}
          onClick={function () {
            if (pdfBusy) return;
            setPdfBusy(true);
            dispatch(uiActions.toastShown(tr2(language, "Preparing the PDF…", "جارٍ تجهيز ملف PDF…")));
            /* ★ صفّ الخادم المختصر؟ نجلب تفاصيله أولاً لتمتلئ الفاتورة */
            const ready =
              order.rowOnly && order.serverId && customerId
                ? fetchServerOrderDetail(Number(customerId), Number(order.serverId)).then(
                    function (detail) { return normalizeServerOrder(detail, {}); },
                    function () { return order; }
                  )
                : Promise.resolve(order);
            ready.then(function (full) {
              const c = (full && full.customer) || {};
              const cname = [c.firstName, c.lastName].filter(Boolean).join(" ") || c.name || "";
              const enriched = Object.assign({}, full, {
                methodLabelText: methodText(full, language),
                statusText: T(full.status, language),
                customerText: [cname, c.phone || c.phoneNumber].filter(Boolean).join(" · "),
                whereText: String((full && full.deliveryMethod) || "")
              });
              downloadInvoicePdf(enriched, language, money).then(
                function () {
                  setPdfBusy(false);
                  dispatch(uiActions.toastShown(tr2(language, "Invoice downloaded (PDF)", "نُزّلت الفاتورة (PDF)")));
                },
                function () {
                  setPdfBusy(false);
                  dispatch(uiActions.toastShown(tr2(language, "Could not create the PDF", "تعذّر إنشاء ملف PDF")));
                }
              );
            });
          }}
        >
          <Icon name="doc" strokeWidth={1.8} />
          <span>{pdfBusy ? tr2(language, "Preparing…", "جارٍ التجهيز…") : "تنزيل الفاتورة PDF"}</span>
        </button>
        <Link className="oh-btn" to={PATHS.perfumes}>
          <Icon name="store" strokeWidth={1.8} />
          <span>تصفّح المتجر</span>
        </Link>
        {/* ★ طلب الخادم لا يُحذف من المتصفح — سجلّه في حسابك دائم */}
        {order.server ? null : (
          <button
            className="oh-btn is-quiet"
            type="button"
            onClick={function () {
              dispatch(ordersActions.orderRemoved(order.invoiceNo));
              dispatch(uiActions.toastShown(tr2(language, "The order was removed from your history", "حُذف الطلب من سجلّك")));
            }}
          >
            <Icon name="trash" strokeWidth={1.8} />
            <span>حذف من السجلّ</span>
          </button>
        )}
      </div>
    </article>
  );
}

export default function OrdersHistory() {
  const dispatch = useAppDispatch();
  const localOrders = useAppSelector(function (s) {
    return s.orders.list;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });
  const location = useLocation();
  const refreshSeenRef = useRef(false);

  /* ★ FE32: الوصول من شاشات الدفع مع refreshInvoices يفتح الفواتير ويحدّثها
     فوراً (قراءة فقط) — «طلباتي — تحديث الحالة» يري الحالة فعلاً. */

  /* ★ طلبات الخادم — تُجلب فقط عند طلب المستخدم (زر «عرض الفواتير»)،
     لا عند فتح الصفحة: صاحب الـ20 طلباً لا يدفع ثمن lag لم يطلبه */
  const [serverRows, setServerRows] = useState([]);
  const [serverLoadedFor, setServerLoadedFor] = useState(null);
  const [serverLoading, setServerLoading] = useState(false);
  const [invoicesOpen, setInvoicesOpen] = useState(false);
  /* ★ تأكيد تفريغ السجلّ: ضغطتان — الأولى تفتح مودال تحذير صريح */
  const [confirmingClear, setConfirmingClear] = useState(false);

  function loadInvoices() {
    setInvoicesOpen(true);
    if (!customerId || serverLoading) return;
    if (serverLoadedFor === Number(customerId)) return;
    setServerLoading(true);
    fetchServerOrders(Number(customerId), 1, 20).then(function (page) {
      setServerRows(((page && page.items) || []).map(normalizeServerRow));
      setServerLoadedFor(Number(customerId));
      setServerLoading(false);
    }, function () {
      /* عطل شبكة؟ المحلي يبقى — بلا تنبيه */
      setServerLoading(false);
    });
  }

  useEffect(function () {
    /* ★ تبدّل الحساب؟ ننسى كاش الخادم السابق */
    setServerRows([]);
    setServerLoadedFor(null);
    setServerLoading(false);
    setInvoicesOpen(false);
  }, [customerId]);

  useEffect(function () {
    var want = false;
    try { want = !!(location && location.state && location.state.refreshInvoices); } catch (e) {}
    if (!want || refreshSeenRef.current) return;
    refreshSeenRef.current = true;
    setInvoicesOpen(true);
    if (!customerId || serverLoading) return;
    setServerLoadedFor(null);
    setServerLoading(true);
    fetchServerOrders(Number(customerId), 1, 20).then(function (page) {
      setServerRows(((page && page.items) || []).map(normalizeServerRow));
      setServerLoadedFor(Number(customerId));
      setServerLoading(false);
    }, function () {
      setServerLoading(false);
    });
    /* عمداً: يُستهلك مرة واحد لكل دخول — location في الاعتماديات */
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [location, customerId]);

  const orders = useMemo(function () {
    if (!invoicesOpen) return [];
    const seen = {};
    const out = [];
    (localOrders || []).concat(serverRows || []).forEach(function (o) {
      const key = String(o.invoiceNo || ("srv-" + (o.serverId || "")));
      if (seen[key]) return;
      seen[key] = true;
      out.push(o);
    });
    out.sort(function (a, b) {
      return (Number(b.createdAt) || 0) - (Number(a.createdAt) || 0);
    });
    return out;
  }, [localOrders, serverRows, invoicesOpen]);

  const shownCount = invoicesOpen ? orders.length : localOrders.length;
  const count = (invoicesOpen ? orders : localOrders).reduce(function (n, o) {
    return n + (o.totals ? o.totals.count : 0);
  }, 0);

  return (
    <section className="oh" id="ordersHistory">
      <header className="oh-top">
        <div>
          <span className="eyebrow">سجلّي</span>
          <h2>
            طلباتي <span className="gold-text">({shownCount})</span>
          </h2>
          <p className="oh-sub">
            {tr2(
              language,
              "Every order you confirmed is saved in your account with its invoice number — ",
              "كل طلب أكّدته محفوظ في حسابك مع رقم فاتورته — "
            )}
            {tr2(language, count + (count === 1 ? " item in total" : " items in total"), count + " قطعة إجمالاً")}
            {tr2(language, ". No bank card is stored with it.", ". ولا نحفظ أرقام البطاقات معه.")}
          </p>
          {/* ★ زر بطاقة طويل: التحميل فقط عند الطلب — بلا lag عند فتح الصفحة */}
          {!invoicesOpen ? (
            <button
              className="btn-primary"
              type="button"
              onClick={loadInvoices}
              style={{ width: "100%", marginTop: "12px", padding: "14px" }}
            >
              <Icon name="doc" strokeWidth={1.8} />
              <span>
                {tr2(language, "Show invoices", "عرض الفواتير")}
                {localOrders.length ? " (" + localOrders.length + ")" : ""}
              </span>
            </button>
          ) : null}
        </div>
        {localOrders.length ? (
          <button
            className="oh-btn is-quiet"
            type="button"
            onClick={function () { setConfirmingClear(true); }}
          >
            <Icon name="trash" strokeWidth={1.8} />
            <span>تفريغ السجلّ</span>
          </button>
        ) : null}
      </header>

      {/* ★ مودال التأكيد — بشديد اللهجة: حذف نهائي من هذا الجهاز فقط */}
      {confirmingClear ? (
        <div className="screen is-open" role="alertdialog" aria-modal="true" aria-labelledby="ohClearTitle">
          <div className="screen-backdrop" onClick={function () { setConfirmingClear(false); }} />
          <div className="screen-panel">
            <div className="screen-head">
              <h2 id="ohClearTitle">
                {tr2(language, "Delete the whole history?", "حذف السجلّ كاملاً؟")}
              </h2>
              <button className="screen-close" type="button" aria-label="إغلاق" onClick={function () { setConfirmingClear(false); }}>
                <Icon name="x" strokeWidth={2} />
              </button>
            </div>
            <div className="screen-body">
              <p className="story-text">
                <b>{tr2(language, "Are you sure?! This cannot be undone.", "هل أنت متأكد؟! لا يمكن التراجع عن هذا.")}</b>
              </p>
              <p className="story-text">
                {tr2(
                  language,
                  "Only the orders saved on THIS device will be deleted. Orders in your server account stay and will reappear when you log in.",
                  "سيُحذف فقط ما هو محفوظ على هذا الجهاز. طلبات حسابك في الخادم تبقى وستعود للظهور عند تسجيل الدخول."
                )}
              </p>
              <div className="wl-empty-actions">
                <button
                  className="btn-primary"
                  type="button"
                  onClick={function () {
                    setConfirmingClear(false);
                    dispatch(ordersActions.ordersCleared());
                    dispatch(uiActions.toastShown(tr2(language, "The order history was cleared", "تم تفريغ سجلّ الطلبات")));
                  }}
                >
                  {tr2(language, "Yes, delete everything", "نعم، احذف كل شيء")}
                </button>
                <button className="btn-ghost" type="button" onClick={function () { setConfirmingClear(false); }}>
                  {tr2(language, "Cancel", "تراجع")}
                </button>
              </div>
            </div>
          </div>
        </div>
      ) : null}

      {!invoicesOpen ? null : serverLoading ? (
        <ListRowsSkeleton count={3} label={tr2(language, "Loading invoices…", "جارٍ تحميل الفواتير…")} />
      ) : orders.length ? (
        <div className="oh-list">
          {orders.map(function (order) {
            return <OrderCard order={order} language={language} customerId={customerId} key={order.invoiceNo} />;
          })}
        </div>
      ) : (
        <div className="oh-empty">
          <span className="oh-empty-ic">
            <Icon name="doc" strokeWidth={1.6} />
          </span>
          <h3>لا توجد طلبات بعد</h3>
          <p>أضف ما يعجبك إلى العربة وأكمل الدفع، وستجد فاتورتك هنا جاهزة في أي وقت.</p>
          <div className="wl-empty-actions">
            <Link className="btn-primary" to={PATHS.perfumes}>
              تصفّح العطور
            </Link>
            <Link className="btn-ghost" to={PATHS.incense}>
              تصفّح البخور
            </Link>
          </div>
        </div>
      )}
    </section>
  );
}
