/* ============================================================
   أطياب الجاسم (React) — أداة فاتورة PDF (invoicePdf)

   تنزيل الفاتورة PDF حقيقي (لا طباعة):
     · الرسم على canvas عالي الدقة (W=1240 ≈ عرض A4 بدقة 150dpi —
       العربية تُشكَّل صحيحة في المتصفح) ثم تُضمَّن الصورة في PDF
       عبر jsPDF (يُحمَّل عند أول تنزيل فقط).
     · كل صفحة PDF تُملأ كاملة بلا هوامش بيضاء (الصورة بملء الصفحة
       0,0,pageW,pageH) — والفواصل بين الصفحات محسوبة على الـcanvas
       نفسه فلا يُقطع أي سطر.
     · المحتوى من سجلّ الطلب نفسه: متى/أين/كيف + كل منتج وسعره +
       خصم الكوبون + التوصيل + الضريبة + الإجمالي — لا أكثر ولا أقل.
   ============================================================ */

let jspdfPromise = null;

function loadJsPdf() {
  if (!jspdfPromise) {
    jspdfPromise = import("https://esm.sh/jspdf@2.5.1").then(function (m) {
      return m.jsPDF || (m.default && m.default.jsPDF) || m.default;
    });
  }
  return jspdfPromise;
}

function fmtDate(ms, lang) {
  const d = new Date(Number(ms) || 0);
  const p = function (n) { return (n < 10 ? "0" : "") + n; };
  const date = p(d.getDate()) + "/" + p(d.getMonth() + 1) + "/" + d.getFullYear();
  const time = p(d.getHours()) + ":" + p(d.getMinutes());
  return { date: date, time: time };
}

function pickName(item, lang) {
  if (lang === "en") return String(item.nameEn || item.name || "");
  return String(item.name || item.nameEn || "");
}

/* يبني أسطر الفاتورة: [{ text, bold, size, color, align, gap }] */
function buildLines(order, language, money) {
  const isEn = language === "en";
  const L = [];
  const T = function (ar, en) { return isEn ? en : ar; };
  const st = fmtDate(order.createdAt, language);
  const cur = order.currency || {};
  const sym = cur.symbolEn || cur.symbol || (isEn ? "AED" : "د.إ");

  L.push({ text: isEn ? "Atyab Al-Jasem" : "أطياب الجاسم", size: 30, bold: true, color: "#c9a24b", center: true });
  L.push({ text: T("فاخر العطور والبخور والعود", "Luxury perfumes, oud & bakhoor"), size: 13, color: "#8a8a8a", center: true, gap: 10 });
  L.push({ text: T("رقم الفاتورة: ", "Invoice: ") + "#" + order.invoiceNo, size: 16, bold: true, gap: 6 });
  L.push({ text: T("التاريخ: ", "Date: ") + st.date + "   " + T("الوقت: ", "Time: ") + st.time, size: 13 });
  L.push({ text: T("الدفع: ", "Payment: ") + (order.methodLabelText || ""), size: 13 });
  if (order.whereText) L.push({ text: T("التوصيل: ", "Delivery: ") + order.whereText, size: 13 });
  if (order.customerText) L.push({ text: T("العميل: ", "Customer: ") + order.customerText, size: 13, gap: 10 });

  L.push({ text: T("المنتجات", "Items"), size: 15, bold: true, color: "#c9a24b", gap: 4 });
  const items = order.items || [];
  if (!items.length && order.rowOnly) {
    L.push({ text: T("عدد القطع: ", "Items count: ") + (order.itemsCount || 0), size: 13 });
  }
  items.forEach(function (it, i) {
    const nm = pickName(it, language);
    const unit = Number(it.unitPrice) || 0;
    const line = Number(it.lineTotal != null ? it.lineTotal : unit * (Number(it.qty) || 1)) || 0;
    L.push({
      text: (i + 1) + ". " + nm + "  × " + it.qty,
      size: 13, gap: 2
    });
    L.push({
      text: T("سعر القطعة: ", "Unit: ") + unit.toFixed(2) + " " + sym + "    " + T("السطر: ", "Line: ") + line.toFixed(2) + " " + sym,
      size: 12, color: "#9a9a9a"
    });
  });

  const t = order.totals || {};
  const f = function (n) { return (Number(n) || 0).toFixed(2) + " " + sym; };
  L.push({ rule: true, gap: 8 });
  if (t.before != null) L.push({ text: T("المجموع الفرعي: ", "Subtotal: ") + f(t.before), size: 13 });
  if (t.code) L.push({ text: T("كوبون الخصم", "Coupon") + " (" + t.code + "): −" + f(t.discount), size: 13, color: "#3ddc84" });
  else if (Number(t.discount) > 0) L.push({ text: T("الخصم: ", "Discount: ") + "−" + f(t.discount), size: 13, color: "#3ddc84" });
  if (Number(t.saved) > 0 && Number(t.saved) !== Number(t.discount)) {
    L.push({ text: T("إجمالي التوفير: ", "Total saved: ") + f(t.saved), size: 13, color: "#3ddc84" });
  }
  L.push({ text: T("التوصيل: ", "Delivery: ") + (Number(t.shipping) > 0 ? f(t.shipping) : T("مجاني", "Free")), size: 13 });
  if (Number(t.vat) > 0) {
    L.push({ text: T("الضريبة (5%): ", "VAT (5%): ") + f(t.vat) + (t.vatIncluded ? T(" (مضمّنة)", " (included)") : ""), size: 13 });
  }
  L.push({ text: T("الإجمالي المستحق: ", "Grand total: ") + f(t.total), size: 17, bold: true, color: "#c9a24b", gap: 6 });
  L.push({ text: T("الحالة: ", "Status: ") + (order.statusText || ""), size: 13, gap: 10 });
  L.push({ text: T("شكراً لتسوقكم من أطياب الجاسم", "Thank you for shopping at Atyab Al-Jasem"), size: 12, color: "#8a8a8a", center: true });
  return L;
}

/* ارتفاع السطر الواحد بالبكسل (قبل الرسم — لحساب فواصل الصفحات) */
function lineHeight(l, fs) {
  if (l.rule) return 30 + (l.gap || 0) * fs;
  return (l.size || 13) * fs + 14 + (l.gap || 0) * fs;
}

/* يرسم الفاتورة كاملة على canvas عالي الدقة ويعيد { cv, pagePx } —
   ارتفاع الـcanvas = عدد صحيح من صفحات A4 (كل صفحة تُملأ لاحقاً
   بملء صفحة PDF بلا هوامش). */
function drawCanvas(lines, isEn) {
  const W = 1240; /* ≈ عرض A4 بدقة 150dpi */
  const FS = W / 794; /* معامل تكبير الخطوط عن النسخة القديمة */
  const pagePx = Math.round((W * 842) / 595); /* ارتفاع صفحة A4 بنفس العرض */
  const pad = 130; /* هامش المحتوى داخل الإطار الذهبي */
  const footZone = 190; /* منطقة التذييل أسفل كل صفحة — لا يدخلها المحتوى */
  const topLead = 150; /* بداية المحتوى أعلى كل صفحة */

  /* ——— المحاكاة أولاً: عدد الصفحات مع احترام فواصل الصفحات ——— */
  let simY = topLead;
  let simPage = 0;
  lines.forEach(function (l) {
    const need = lineHeight(l, FS);
    if (simY + need > (simPage + 1) * pagePx - footZone) {
      simPage += 1;
      simY = simPage * pagePx + topLead;
    }
    simY += need;
  });
  simY += 200; /* فسحة التوقيع + رقم الصفحة في الأخيرة */
  const pages = Math.max(1, Math.ceil(simY / pagePx));
  const H = pages * pagePx;

  const cv = document.createElement("canvas");
  cv.width = W;
  cv.height = H;
  const ctx = cv.getContext("2d");
  try { ctx.direction = isEn ? "ltr" : "rtl"; } catch (e) {}
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, W, H);

  /* شريط ذهبي أعلى الأولى وأسفل الأخيرة */
  ctx.fillStyle = "#c9a24b";
  ctx.fillRect(0, 0, W, 16);
  ctx.fillRect(0, H - 16, W, 16);

  /* إطار ذهبي داخلي لكل صفحة — يعطي إحساس الامتلاء والفخامة */
  ctx.strokeStyle = "#c9a24b";
  ctx.lineWidth = 3;
  for (let i = 0; i < pages; i++) {
    ctx.strokeRect(44, i * pagePx + 44, W - 88, pagePx - 88);
  }

  /* ——— رسم المحتوى مع نفس منطق الفواصل ——— */
  const fontOf = function (l) {
    return (l.bold ? "bold " : "") + Math.round((l.size || 13) * FS) + 'px "Segoe UI", Tahoma, Arial, sans-serif';
  };
  let y = topLead;
  let page = 0;
  lines.forEach(function (l) {
    const need = lineHeight(l, FS);
    if (y + need > (page + 1) * pagePx - footZone) {
      page += 1;
      y = page * pagePx + topLead;
    }
    if (l.rule) {
      y += 8;
      ctx.strokeStyle = "#cccccc";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(pad, y);
      ctx.lineTo(W - pad, y);
      ctx.stroke();
      y += 22 + (l.gap || 0) * FS;
      return;
    }
    ctx.font = fontOf(l);
    ctx.fillStyle = l.color || "#1a1a1a";
    ctx.textBaseline = "top";
    if (l.center) {
      ctx.textAlign = "center";
      ctx.fillText(l.text, W / 2, y, W - pad * 2);
    } else if (isEn) {
      ctx.textAlign = "left";
      ctx.fillText(l.text, pad, y, W - pad * 2);
    } else {
      ctx.textAlign = "right";
      ctx.fillText(l.text, W - pad, y, W - pad * 2);
    }
    y += need;
  });

  /* التوقيع في الأخيرة */
  ctx.font = '17px "Segoe UI", Tahoma, Arial';
  ctx.fillStyle = "#999999";
  ctx.textAlign = "center";
  ctx.fillText(isEn ? "Atyab Al-Jasem — electronic invoice" : "أطياب الجاسم — فاتورة إلكترونية", W / 2, H - 150);

  /* ترقيم الصفحات */
  ctx.font = '17px "Segoe UI", Tahoma, Arial';
  ctx.fillStyle = "#999999";
  for (let i = 0; i < pages; i++) {
    const label = isEn ? "Page " + (i + 1) + " of " + pages : "صفحة " + (i + 1) + " من " + pages;
    ctx.fillText(label, W / 2, (i + 1) * pagePx - 105);
  }
  return { cv: cv, pagePx: pagePx, pages: pages };
}

export async function downloadInvoicePdf(order, language, money) {
  const isEn = language === "en";
  const JsPDF = await loadJsPdf();
  const lines = buildLines(order, language, money);
  const drawn = drawCanvas(lines, isEn);
  const cv = drawn.cv;
  const pagePx = drawn.pagePx;
  const pages = drawn.pages;
  const doc = new JsPDF({ unit: "pt", format: "a4" });
  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  for (let i = 0; i < pages; i++) {
    const pc = document.createElement("canvas");
    pc.width = cv.width;
    pc.height = pagePx;
    pc.getContext("2d").drawImage(cv, 0, i * pagePx, cv.width, pagePx, 0, 0, cv.width, pagePx);
    if (i > 0) doc.addPage();
    /* بملء الصفحة كاملة — بلا هوامش بيضاء (جوال ولابتوب) */
    doc.addImage(pc.toDataURL("image/png"), "PNG", 0, 0, pageW, pageH);
  }
  doc.save("invoice-" + String(order.invoiceNo || "order") + ".pdf");
  return true;
}
