/* ============================================================
   أطياب الجاسم (React) — صفحة معلومات المستخدم (UserInfoPage)

   تعرض بالترتيب: الكلام الموجود أعلى الصفحة، ثم زر
   «عرض قائمة رغباتي» (Show my Wish List) الذي ينقل إلى صفحة الأمنيات،
   ثم كومبوننت UserInfo (أقسامه الأربعة: البطاقة الجانبية · البيانات
   الأساسية · العنوان · شريط الحالة).

   ★ الحفظ يمرّ من validation.js ثم إلى Redux (userSlice) ثم إلى
     localStorage على هذا الجهاز — والتحقّق لا يثق بالواجهة وحدها.
   ============================================================ */

import { Link } from "react-router-dom";
import { PATHS } from "../routes.js";
import { usePageMeta } from "../usePageMeta.js";
import { useAppSelector } from "../redux/hooks.js";
import { tr2 } from "../i18n.js";
import UserInfo from "../components/UserExperience/UserInfo.jsx";
import OrdersHistory from "../components/UserExperience/OrdersHistory.jsx";
import { Icon } from "../components/Source/Icons.jsx";

export default function UserInfoPage() {
  usePageMeta({ route: "profile", titleAr: "حسابي", titleEn: "My account" });

  const profile = useAppSelector(function (s) {
    return s.user.profile;
  });
  const session = useAppSelector(function (s) {
    return s.user.session;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const firstName = profile.firstName || "";
  const greeting = firstName
    ? tr2(language, "Welcome, ", "أهلاً ") + firstName
    : tr2(language, "Welcome to your account", "أهلاً بك في حسابك");

  return (
    <section className="container view pf" id="profileView">
      <div className="pf-top">
        <Link className="pf-back" to={PATHS.perfumes}>
          <Icon name="back" strokeWidth={2} />
          <span>رجوع إلى العطور</span>
        </Link>
        <span className="pf-crumb">
          {tr2(language, "My account /", "حسابي /")} <b>{tr2(language, "My details", "معلوماتي")}</b>
        </span>
      </div>

      <div className="pf-hero">
        <div className="pf-hero-copy">
          <span className="eyebrow">{tr2(language, "My account", "حسابي")}</span>
          <h1>{greeting}</h1>
          <p className="pf-sub">
            {tr2(
              language,
              "Add your details, choose the region, language and currency you prefer to shop in, then complete your delivery address — we will use them for your upcoming orders. ",
              "أضف بياناتك واختر المنطقة واللغة والعملة التي تفضّل التسوّق بها، ثم أكمل عنوان التوصيل — وسنستخدمها في طلباتك القادمة. "
            )}
            {session ? "" : tr2(language, "Create an account or log in to follow your orders.", "أنشئ حساباً أو سجّل الدخول لتتابع طلباتك.")}
          </p>
        </div>

        <Link className="pf-wish" to={PATHS.wishlist}>
          <Icon name="heart" strokeWidth={1.8} />
          <span>
            {tr2(language, "My wishlist", "قائمة رغباتي")}
            <small>{tr2(language, "Items you saved with the heart", "القطع التي حفظتها بعلامة القلب")}</small>
          </span>
        </Link>
      </div>

      <UserInfo />

      {/* سجلّ الطلبات — كل طلب أكّده العميل محفوظ على هذا الجهاز */}
      <OrdersHistory />
    </section>
  );
}
