/* ============================================================
   أطياب الجاسم (React) — بطاقة شحنة الطلب (OP1)

   تُعرض داخل بطاقة الطلب في «طلباتي» عند طلب العميل («حالة الشحنة») —
   لا تُجلب تلقائياً لكل الطلبات، ولا تُستطلع إلا أثناء فتح تفاصيل طلب
   نشط، وتتوقف عند إخفاء الصفحة أو إغلاق البطاقة أو الحالة النهائية
   أو المغادرة/تبديل الحساب (backoff + حد زمني + منع تداخل).

   القواعد (OP1):
   · القراءة فقط عبر REST أطياب — لا SendOrder/Start/Create من العرض.
   · المجموعة الخماسي (Pending/Returned/Cancelled/Delivered/InTheWay)
     + detail/detailAr من الباك — لا قائمة محلية ولا إعادة تصنيف.
   · المحطة من progressStage الموثوق وحده — تُعرض كنص مرحلة، لا حركة
     زمنية ولا تسليم مستنتج. Half Delivered ضمن Delivered لكن بلا
     علامة اكتمال شامل. Returned/Cancelled استثنائيان بلا تقدم.
   · الحالة الموثوقة الجديدة تُقبل دائماً (Returned بعد Delivered مسموح).
   · الردود القديمة (طلب سابق/حساب سابق) تُتجاهل (orderId/account guard).
   · زر الإلغاء بإذن الباك فقط + تأكيد المستخدم؛ بعد الإرسال: «تم إرسال
     طلب الإلغاء» — لا تغيير محلي لأي حالة؛ الحسم للباك والشركة.
   · idempotency ثابتة لكل طلب منطقي (نفس المفتاح عند إعادة/انقطاع).
   · فشل قراءة الشحنة لا يغيّر حالة الطلب/الدفع.
   · shouldPoll=false يوقف فوراً حتى لو غير نهائية.
   · لا delivered محسوب من التاريخ — الموثقة وحدها.
   · COD لا يُسمّى «مدفوعاً» لمجرد التأكيد/التسليم.
   · لا ClientNo ولا raw URLs ولا stack traces ولا رموز خام — رسائل
     عربية آمنة فقط (+ شارة وضع تجريبي محلي في المحاكاة).
   ============================================================ */

import { useEffect, useRef, useState } from "react";
import { Link } from "react-router-dom";
import { useAppSelector } from "../../redux/hooks.js";
import { tr2 } from "../../i18n.js";
import { Icon } from "../Source/Icons.jsx";
import { PATHS } from "../../routes.js";
import {
  SHIPPING_SIMULATION, SHIPPING_SIMULATION_NOTE,
  SHIPMENT_ACTIVE_POLL_MS, SHIPMENT_POLL_MIN_MS, SHIPMENT_POLL_MAX_MS,
  SHIPMENT_POLL_MAX_ATTEMPTS, SHIPMENT_POLL_MAX_DURATION_MS,
  fetchOrderShipmentOP1, requestShipmentCancellation,
  getOrCreateCancelIdempotencyKey,
  op1GroupMeta, op1DetailText, op1StageMeta,
  shouldContinueOP1Poll, nextShipmentPollDelay,
  formatContractDay, classifyTrackingError
} from "../../api/shipping.js";
import { TrackSkeleton } from "../Skeletons/index.js";
import "../Skeletons/Skeletons.css";

function stampDay(value, language) {
  let out = "";
  try {
    out = formatContractDay(value, language).text;
  } catch (e) {
    out = "";
  }
  return out;
}

export default function ShipmentCard(props) {
  const order = props.order || {};
  const language = props.language || "ar";
  const serverId = Number(order.serverId) || 0;
  const customerId = useAppSelector(function (s) {
    return (s.user && s.user.auth && s.user.auth.customerId) || null;
  });

  const [open, setOpen] = useState(false);
  const [ship, setShip] = useState(null);
  /* idle | loading | ready | error */
  const [loadState, setLoadState] = useState("idle");
  const [loadError, setLoadError] = useState("");
  /* idle | confirm | busy | done | error */
  const [cancelState, setCancelState] = useState("idle");
  const [cancelMsg, setCancelMsg] = useState("");
  const seqRef = useRef(0);
  const openOrderRef = useRef(0);
  const openCustomerRef = useRef(null);
  const pollStartRef = useRef(0);
  const pollAttemptsRef = useRef(0);
  const pollInflightRef = useRef(false);
  const cancelKeyRef = useRef("");

  function load(force) {
    const seq = (seqRef.current = (Number(seqRef.current) || 0) + 1);
    const myOrder = Number(serverId) || 0;
    const myCustomer = customerId != null ? Number(customerId) : null;
    setLoadState("loading");
    setLoadError("");
    fetchOrderShipmentOP1(myOrder, { force: !!force }).then(function (norm) {
      if (seq !== seqRef.current) return;
      /* ★ تجاهل الاستجابات القديمة: طلب سابق أو حساب سابق. */
      if (Number(serverId) !== myOrder) return;
      if (myCustomer != null && customerId != null && Number(customerId) !== myCustomer) return;
      if (norm && norm.orderId && Number(norm.orderId) !== myOrder) return;
      setShip(norm);
      setLoadState("ready");
    }, function (err) {
      if (seq !== seqRef.current) return;
      if (Number(serverId) !== myOrder) return;
      if (myCustomer != null && customerId != null && Number(customerId) !== myCustomer) return;
      const c = classifyTrackingError(err, false);
      setLoadState("error");
      setLoadError(c.message);
    });
  }

  function toggle() {
    if (open) {
      seqRef.current = (Number(seqRef.current) || 0) + 1;
      pollInflightRef.current = false;
      setOpen(false);
      return;
    }
    setOpen(true);
    openOrderRef.current = Number(serverId) || 0;
    openCustomerRef.current = customerId != null ? Number(customerId) : null;
    pollStartRef.current = Date.now();
    pollAttemptsRef.current = 0;
    if (loadState !== "ready") load(false);
  }

  /* ★ المتابعة أثناء فتح التفاصيل فقط — بفاصل الباك (أو الافتراضي) مع
     backoff + حد زمني + منع تداخل، وتتوقف عند النهائية (OP1)/الإخفاء/
     المغادرة. shouldPoll=false يوقف فوراً. */
  /* ★ بدائيات القرار (لا كائن ship كله في التبعيات — هويته تتجدد مع كل رد).
     كل قيمة تُقارن بقيمتها: أي تبدّل يعيد تقييم الحراس فوراً بدل إغلاق قديم. */
  const shipPresent = !!ship;
  const shipGroup = ship && ship.group;
  const shipMismatch = !!(ship && ship.contractMismatch);
  const shipShouldPollOff = !!(ship && ship.shouldPoll === false);
  const shipShouldPollRaw = ship ? ship.shouldPoll : undefined;
  const shipPollMs = ship ? ship.pollIntervalMs : undefined;
  /* ★ مرآة حية للحساب تُقرأ داخل tick — الأثر لا يعتمد المعرف مباشرة
     فيبقى إيقاع إعادة التشغيل كما كان، مع كشف تبدّل الحساب فعلاً. */
  const liveCustomerRef = useRef(customerId);
  useEffect(function () { liveCustomerRef.current = customerId; }, [customerId]);
  useEffect(function () {
    /* ★ OP3 §1: شرط التنفيذ داخل الأثر — بلا serverId لا شيء يُجلب. */
    if (!serverId) return;
    if (!open || !shipPresent) return;
    if (shipMismatch) return;
    if (shipShouldPollOff) return;
    if (op1GroupMeta(shipGroup).final) return;
    let alive = true;
    let timer = 0;
    const base = shipPollMs && Number(shipPollMs) > 0 ? Number(shipPollMs) : SHIPMENT_ACTIVE_POLL_MS;
    function tick() {
      if (!alive) return;
      /* ★ المغادرة: إغلاق/تبديل طلب/حساب = توقف بلا كتابة. */
      if (Number(serverId) !== Number(openOrderRef.current)) return;
      if (openCustomerRef.current != null && liveCustomerRef.current != null && Number(liveCustomerRef.current) !== Number(openCustomerRef.current)) return;
      try {
        if (typeof document !== "undefined" && document.hidden) {
          timer = setTimeout(function () { if (alive) tick(); }, 5000);
          return;
        }
      } catch (e) {}
      var gate = null;
      try {
        gate = shouldContinueOP1Poll({
          group: shipGroup,
          shouldPoll: shipShouldPollRaw,
          contractMismatch: shipMismatch,
          attempts: pollAttemptsRef.current,
          startedAtMs: pollStartRef.current,
          nowMs: Date.now(),
          maxAttempts: SHIPMENT_POLL_MAX_ATTEMPTS,
          maxDurationMs: SHIPMENT_POLL_MAX_DURATION_MS,
          departed: false
        });
      } catch (eG) { gate = { cont: true }; }
      if (!gate || !gate.cont) return;
      if (pollInflightRef.current) {
        timer = setTimeout(function () { if (alive) tick(); }, 5000);
        return;
      }
      pollInflightRef.current = true;
      pollAttemptsRef.current += 1;
      fetchOrderShipmentOP1(Number(serverId), { force: true }).then(function (norm) {
        pollInflightRef.current = false;
        if (!alive) return;
        if (Number(serverId) !== Number(openOrderRef.current)) return;
        if (openCustomerRef.current != null && liveCustomerRef.current != null && Number(liveCustomerRef.current) !== Number(openCustomerRef.current)) return;
        /* ★ قبول الحالة الموثوقة الجديدة دائماً — حتى Returned بعد Delivered. */
        setShip(norm);
        setLoadState("ready");
        if (op1GroupMeta(norm.group).final) return;
        const delay = nextShipmentPollDelay(pollAttemptsRef.current, base);
        timer = setTimeout(function () { if (alive) tick(); }, delay);
      }, function () {
        pollInflightRef.current = false;
        /* ★ خطأ المتابعة يُتجاهل بصمت — آخر حالة موثقة تبقى معروضة،
           وفشل القراءة لا يغيّر طلباً/دفعاً. */
        if (!alive) return;
        const delay = nextShipmentPollDelay(pollAttemptsRef.current, base);
        timer = setTimeout(function () { if (alive) tick(); }, delay);
      });
    }
    const firstDelay = nextShipmentPollDelay(0, base);
    timer = setTimeout(function () { tick(); }, Math.max(SHIPMENT_POLL_MIN_MS, Math.min(SHIPMENT_POLL_MAX_MS, firstDelay)));
    function onVis() {
      try {
        if (!document.hidden) { /* تُستأنف عند العودة عبر الجدول القائم */ }
      } catch (e) {}
    }
    try { document.addEventListener("visibilitychange", onVis); } catch (e) {}
    return function () {
      alive = false;
      pollInflightRef.current = false;
      try { clearTimeout(timer); } catch (e) {}
      try { document.removeEventListener("visibilitychange", onVis); } catch (e) {}
    };
  }, [open, shipPresent, shipGroup, shipMismatch, shipShouldPollOff, shipShouldPollRaw, shipPollMs, serverId]);

  /* ★ OP3 §1: الخروج المشروط هنا — بعد كل Hooks (useState/useRef/useEffect
     أعلاه تُستدعى دائماً وبنفس الترتيب، بلا return مبكر يقصيها). بلا معرف
     خادمي (طلب محلي قديم)؟ لا بطاقة شحنة — حالة التوصيل القائم في البطاقة
     الأم تكفي، بلا تخمين رقم شحنة. شروط التنفيذ داخل useEffect نفسه. */
  if (!serverId) return null;

  function askCancel() {
    setCancelMsg("");
    setCancelState("confirm");
  }

  function sendCancel() {
    if (cancelState === "busy") return;
    /* ★ مفتاح ثابت لكل طلب منطقي — نفس المفتاح عند كل إعادة/انقطاع
       لنفس الطلب (لا مفتاح عشوائي جديد لكل إعادة شبكة). */
    if (!cancelKeyRef.current) {
      try {
        cancelKeyRef.current = getOrCreateCancelIdempotencyKey(Number(serverId), "customer_request");
      } catch (e) {
        cancelKeyRef.current = "";
      }
    }
    setCancelState("busy");
    setCancelMsg("");
    requestShipmentCancellation(Number(serverId), { reason: "customer_request", idempotencyKey: cancelKeyRef.current }).then(function (r) {
      setCancelState("done");
      setCancelMsg((r && r.message) || "تم إرسال طلب الإلغاء");
      /* ★ لا تغيير محلي لحالة الشحنة — الحسم للباك والشركة. */
    }, function (err) {
      const c = classifyTrackingError(err, false);
      setCancelState("error");
      setCancelMsg(c.kind === "cancellation_not_allowed"
        ? "تعذّر طلب الإلغاء — خدمة العملاء تعالج الحالة."
        : c.message);
    });
  }

  const meta = ship ? op1GroupMeta(ship.group, language) : null;
  const detail = ship ? op1DetailText(ship, language) : "";
  const stageMeta = ship && ship.progressStage != null ? op1StageMeta(ship.progressStage, language) : null;
  const updated = ship && ship.lastUpdatedAt ? stampDay(ship.lastUpdatedAt, language) : "";

  return (
    <div className="oh-ship">
      <button className="oh-btn" type="button" onClick={toggle} aria-expanded={open ? "true" : "false"}>
        <Icon name="truck" strokeWidth={1.8} />
        <span>{open ? tr2(language, "Hide shipment", "إخفاء الشحنة") : tr2(language, "Shipment status", "حالة الشحنة")}</span>
      </button>
      {open ? (
        <div className="oh-ship-body" role="status">
          {loadState === "loading" && !ship ? (
            <TrackSkeleton />
          ) : null}
          {loadState === "error" && !ship ? (
            <p className="ck-hint">
              {loadError}
              <button className="ck-edit" type="button" onClick={function () { load(true); }}>
                {tr2(language, "Retry", "إعادة المحاولة")}
              </button>
            </p>
          ) : null}
          {ship && ship.contractMismatch ? (
            <p className="ck-auth-warn" role="alert">
              {tr2(language, "Shipment status changed — please refresh.", "تغيّرت صيغة حالة الشحنة — حدّث الصفحة وحاول مجدداً.")}
            </p>
          ) : null}
          {ship && !ship.group && ship.hasVoucher ? (
            <p className="ck-auth-warn" role="alert">{tr2(language, "Shipment status unavailable", "تعذّر قراءة حالة الشحنة")}</p>
          ) : null}
          {ship && !ship.contractMismatch && (ship.group || !ship.hasVoucher) ? (
            <div>
              <p className="oh-ship-line">
                <b>{meta ? meta.label : ""}</b>
                {ship.isStale ? (
                  <span className="ck-hint">
                    {" "}· {tr2(language, "This may be outdated", "قد تكون قديمة")}
                    {updated ? " — " + tr2(language, "last update: ", "آخر تحديث: ") + updated : ""}
                  </span>
                ) : (
                  updated ? <span className="ck-hint">{" "}· {tr2(language, "last update: ", "آخر تحديث: ") + updated}</span> : null
                )}
              </p>
              {detail ? <p className="oh-ship-line">{detail}</p> : null}
              {ship.group === "Delivered" && ship.isFullyDelivered === false ? (
                <p className="ck-hint">{tr2(language, "Partial delivery — not fully completed.", "تسليم جزئي — لم يكتمل التسليم بالكامل.")}</p>
              ) : null}
              {ship.exceptional ? (
                <p className="ck-hint">
                  {ship.group === "Returned"
                    ? tr2(language, "Exceptional path — returns do not move forward.", "مسار استثنائي — المرتجع لا يتحرك للأمام.")
                    : tr2(language, "Exceptional path — cancellations do not move forward.", "مسار استثنائي — الملغي لا يتحرك للأمام.")}
                </p>
              ) : null}
              {stageMeta && !ship.exceptional ? (
                <p className="oh-ship-line">
                  {tr2(language, "Stage: ", "المرحلة: ")}{stageMeta.stage} — {stageMeta.label}
                </p>
              ) : null}
              {ship.voucherNo ? (
                <p className="oh-ship-line">
                  {tr2(language, "Shipment no.: ", "رقم الشحنة: ")}<b dir="ltr">{ship.voucherNo}</b>
                </p>
              ) : (
                <p className="ck-hint">{tr2(language, "No shipment number yet — normal at this stage.", "لا يوجد رقم شحنة بعد — وهذا طبيعي في هذه المرحلة.")}</p>
              )}
              {ship.needsAttention ? (
                <p className="ck-hint" role="status">{detail || tr2(language, "This shipment needs follow-up.", "هذه الشحنة تحتاج متابعة.")}</p>
              ) : null}
              <p className="ck-hint">
                <Link to={PATHS.tracking}>{tr2(language, "Detailed tracking", "تتبع مفصّل")}</Link>
              </p>
              {SHIPPING_SIMULATION || ship.simulated ? (
                <p className="ck-hint">{"(" + SHIPPING_SIMULATION_NOTE + ")"}</p>
              ) : null}
              {ship.canRequestCancellation && cancelState !== "done" ? (
                <div className="oh-ship-cancel">
                  {cancelState === "confirm" ? (
                    <p role="alert">
                      <span>{tr2(language, "Send a cancellation request for this shipment?", "إرسال طلب إلغاء لهذه الشحنة؟")}</span>
                      <span className="oh-ship-confirm-btns">
                        <button className="oh-btn is-gold" type="button" disabled={cancelState === "busy"} onClick={sendCancel}>
                          {tr2(language, "Confirm", "تأكيد الإرسال")}
                        </button>
                        <button className="oh-btn is-quiet" type="button" onClick={function () { setCancelState("idle"); setCancelMsg(""); }}>
                          {tr2(language, "Back", "تراجع")}
                        </button>
                      </span>
                    </p>
                  ) : (
                    <button className="oh-btn is-quiet" type="button" disabled={cancelState === "busy"} onClick={askCancel}>
                      <span>{cancelState === "busy" ? tr2(language, "Sending…", "جارٍ الإرسال…") : tr2(language, "Request cancellation", "طلب الإلغاء")}</span>
                    </button>
                  )}
                </div>
              ) : null}
              {cancelMsg ? (
                <p className={cancelState === "error" ? "ck-auth-warn" : "ck-hint"} role={cancelState === "error" ? "alert" : "status"}>
                  {cancelMsg}
                </p>
              ) : null}
            </div>
          ) : null}
        </div>
      ) : null}
    </div>
  );
}
